Una cadena de vagones de un tren; cada vagón tiene un número y se quieren quitar los de un número averiado.

function quitarVagones(primero, averiado) {
  const inicio = { numero: 0, siguiente: primero };
  let actual = inicio;
  while (actual.siguiente !== null) {
    if (actual.siguiente.numero === averiado) {
      actual.siguiente = actual.siguiente.siguiente;
    } else {
      actual = actual.siguiente;
    }
  }
  return inicio.siguiente;
}
